#!/usr/bin/env python3
"""Diagnose MCP configuration sources without exposing credentials."""

import argparse
import json
import os
import sys
from pathlib import Path

CLIENT_PATHS = {
    ("claude", "global"): lambda home, workspace: home / ".claude.json",
    ("claude", "local"): lambda home, workspace: workspace / ".mcp.json",
    ("vscode", "local"): lambda home, workspace: workspace / ".vscode" / "mcp.json",
    ("kiro", "global"): lambda home, workspace: home / ".kiro" / "settings" / "mcp.json",
    ("kiro", "local"): lambda home, workspace: workspace / ".kiro" / "settings" / "mcp.json",
    ("opencode", "global"): lambda home, workspace: home / ".config" / "opencode" / "opencode.json",
    ("opencode", "local"): lambda home, workspace: workspace / "opencode.json",
}

SERVER_KEYS = {
    "jira": "mi-jira",
    "feishu": "feishu-mcp",
    "gerrit": "gerrit",
}

EXPECTED_URLS = {
    "jira": "https://acc.pt.miui.com/jira-mcp/mcp",
}


def config_path(client, scope, home, workspace):
    resolver = CLIENT_PATHS.get((client, scope))
    if resolver is None:
        raise ValueError(f"unsupported client/scope: {client}/{scope}")
    return resolver(home, workspace)


def server_container(config, client):
    if client == "vscode":
        return config.get("servers"), "servers"
    if client == "opencode":
        return config.get("mcp"), "mcp"
    return config.get("mcpServers"), "mcpServers"


def inspect_server(kind, entry, client):
    errors = []
    warnings = []
    credentials_present = None

    if not isinstance(entry, dict):
        return False, credentials_present, ["server entry is not an object"], warnings

    if kind == "jira":
        if entry.get("url", "").rstrip("/") != EXPECTED_URLS["jira"]:
            errors.append("unexpected Jira MCP URL")
        headers = entry.get("headers")
        required = (
            "X-Atlassian-Jira-Url",
            "X-Atlassian-Username",
            "X-Atlassian-Jira-Personal-Token",
        )
        credentials_present = isinstance(headers, dict) and all(headers.get(key) for key in required)
        if not credentials_present:
            errors.append("required Jira headers are missing")
    elif kind == "feishu":
        url = entry.get("url", "")
        credentials_present = url.startswith("https://mcp.feishu.cn/mcp/mcp_")
        if not credentials_present:
            errors.append("Feishu MCP URL is missing or malformed")
    elif kind == "gerrit":
        command = entry.get("command")
        credentials_present = bool(command)
        if entry.get("type") != "stdio" and client != "kiro":
            errors.append("Gerrit MCP must use stdio")
        if not command:
            errors.append("Gerrit MCP command is missing")
        elif not Path(os.path.expanduser(command)).is_file():
            errors.append("Gerrit MCP command does not exist")
        elif not os.access(os.path.expanduser(command), os.X_OK):
            errors.append("Gerrit MCP command is not executable")

    if entry.get("disabled") is True or entry.get("enabled") is False:
        errors.append("server is disabled")

    if client == "vscode" and entry.get("type") not in ("http", "stdio"):
        errors.append("VS Code server type is missing or invalid")
    if client == "opencode" and entry.get("type") != "remote" and kind != "gerrit":
        errors.append("OpenCode remote server type is invalid")

    return not errors, credentials_present, errors, warnings


def candidate_paths(home, workspace):
    return [
        home / ".claude.json",
        workspace / ".mcp.json",
        workspace / ".vscode" / "mcp.json",
        home / ".claude" / "mcp.json",
        home / ".claude" / "settings.json",
        workspace / ".claude" / "settings.json",
        home / ".kiro" / "settings" / "mcp.json",
        workspace / ".kiro" / "settings" / "mcp.json",
        home / ".config" / "opencode" / "opencode.json",
        workspace / "opencode.json",
    ]


def find_server_names(path):
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return []
    names = set()
    for key in ("mcpServers", "servers", "mcp"):
        value = data.get(key)
        if isinstance(value, dict):
            names.update(value)
    return sorted(names)


def extension_version(home):
    root = home / ".vscode" / "extensions"
    versions = []
    if root.is_dir():
        for path in root.glob("anthropic.claude-code-*-linux-x64"):
            versions.append(path.name.removeprefix("anthropic.claude-code-").removesuffix("-linux-x64"))
    return sorted(versions)[-1] if versions else None


def diagnose(args):
    home = Path(args.home).expanduser().resolve()
    workspace = Path(args.workspace_root).expanduser().resolve()
    try:
        target = config_path(args.client, args.scope, home, workspace)
    except ValueError as exc:
        return {"ready": False, "errors": [str(exc)], "warnings": []}, 2

    result = {
        "host": args.host,
        "client": args.client,
        "scope": args.scope,
        "extension_version": extension_version(home) if args.client == "claude" else None,
        "config_path": str(target),
        "config_exists": target.is_file(),
        "json_valid": False,
        "container_key": None,
        "servers": {},
        "conflicting_files": [],
        "credentials_redacted": True,
        "ready": False,
        "errors": [],
        "warnings": [],
    }

    if not target.is_file():
        result["errors"].append("effective config file does not exist")
    else:
        try:
            config = json.loads(target.read_text(encoding="utf-8"))
            result["json_valid"] = True
        except json.JSONDecodeError as exc:
            result["errors"].append(f"invalid JSON at line {exc.lineno}, column {exc.colno}")
            config = None
        except OSError as exc:
            result["errors"].append(f"cannot read config: {exc}")
            config = None

        if isinstance(config, dict):
            container, container_key = server_container(config, args.client)
            result["container_key"] = container_key
            if not isinstance(container, dict):
                result["errors"].append(f"missing {container_key} object")
            else:
                kinds = SERVER_KEYS if args.server == "all" else {args.server: SERVER_KEYS[args.server]}
                for kind, name in kinds.items():
                    present = name in container
                    detail = {
                        "name": name,
                        "present": present,
                        "schema_valid": False,
                        "credentials_present": None,
                        "errors": [],
                        "warnings": [],
                    }
                    if present:
                        valid, credentials, errors, warnings = inspect_server(kind, container[name], args.client)
                        detail.update(
                            schema_valid=valid,
                            credentials_present=credentials,
                            errors=errors,
                            warnings=warnings,
                        )
                        result["errors"].extend(f"{name}: {message}" for message in errors)
                        result["warnings"].extend(f"{name}: {message}" for message in warnings)
                    else:
                        detail["errors"].append("server is not configured")
                        result["errors"].append(f"{name}: server is not configured")
                    result["servers"][kind] = detail

    target_resolved = target.resolve(strict=False)
    for path in candidate_paths(home, workspace):
        if path.resolve(strict=False) == target_resolved or not path.is_file():
            continue
        names = find_server_names(path)
        relevant = sorted(set(names) & set(SERVER_KEYS.values()))
        if relevant:
            result["conflicting_files"].append({"path": str(path), "servers": relevant})

    if result["conflicting_files"]:
        result["warnings"].append("MCP entries also exist in non-effective or other-client config files")

    result["ready"] = not result["errors"]
    return result, 0 if result["ready"] else 1


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", choices=["vscode", "kiro", "cli", "opencode"], required=True)
    parser.add_argument("--client", choices=["claude", "vscode", "kiro", "opencode"], required=True)
    parser.add_argument("--scope", choices=["local", "global"], required=True)
    parser.add_argument("--server", choices=["all", "jira", "feishu", "gerrit"], default="all")
    parser.add_argument("--workspace-root", required=True)
    parser.add_argument("--home", default=str(Path.home()), help=argparse.SUPPRESS)
    args = parser.parse_args()

    result, code = diagnose(args)
    json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")
    return code


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Safely add or update the mi-jira MCP configuration."""

import argparse
import getpass
import json
import os
import shutil
import stat
import sys
import tempfile
from pathlib import Path

JIRA_MCP_URL = "https://acc.pt.miui.com/jira-mcp/mcp"
DEFAULT_JIRA_URL = "https://jira.n.xiaomi.com"
TOKEN_ENV = "JIRA_MCP_TOKEN"


def resolve_config_path(client, scope, home, workspace):
    paths = {
        ("claude", "global"): home / ".claude.json",
        ("claude", "local"): workspace / ".mcp.json",
        ("vscode", "local"): workspace / ".vscode" / "mcp.json",
        ("kiro", "global"): home / ".kiro" / "settings" / "mcp.json",
        ("kiro", "local"): workspace / ".kiro" / "settings" / "mcp.json",
        ("opencode", "global"): home / ".config" / "opencode" / "opencode.json",
        ("opencode", "local"): workspace / "opencode.json",
    }
    try:
        return paths[(client, scope)]
    except KeyError as exc:
        raise ValueError(f"unsupported client/scope: {client}/{scope}") from exc


def read_config(path):
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(
            f"invalid JSON in {path} at line {exc.lineno}, column {exc.colno}"
        ) from exc
    if not isinstance(data, dict):
        raise ValueError(f"top-level JSON in {path} must be an object")
    return data


def read_token(args):
    token = os.environ.get(TOKEN_ENV)
    if not token and args.token_stdin:
        token = sys.stdin.readline().rstrip("\r\n")
    if not token and sys.stdin.isatty() and not args.dry_run:
        token = getpass.getpass("Jira Personal Access Token: ")
    if args.dry_run and not token:
        return "<redacted>"
    if not token:
        raise ValueError(
            f"token is required via {TOKEN_ENV}, --token-stdin, or secure prompt"
        )
    return token


def build_entry(client, username, token, jira_url):
    headers = {
        "X-Atlassian-Jira-Url": jira_url,
        "X-Atlassian-Username": username,
        "X-Atlassian-Jira-Personal-Token": token,
    }
    if client == "opencode":
        return {
            "type": "remote",
            "url": JIRA_MCP_URL + "/",
            "headers": headers,
            "enabled": True,
        }
    if client == "kiro":
        return {
            "url": JIRA_MCP_URL,
            "transport": "http",
            "headers": headers,
            "disabled": False,
        }
    return {"type": "http", "url": JIRA_MCP_URL, "headers": headers}


def merge_config(config, client, entry):
    result = dict(config)
    if client == "vscode":
        result.setdefault("inputs", [])
        container_key = "servers"
    elif client == "opencode":
        container_key = "mcp"
    else:
        container_key = "mcpServers"

    container = result.get(container_key)
    if container is None:
        container = {}
    if not isinstance(container, dict):
        raise ValueError(f"{container_key} must be an object")
    container = dict(container)
    container["mi-jira"] = entry
    result[container_key] = container

    if client == "opencode":
        permissions = result.get("permission", {})
        if not isinstance(permissions, dict):
            raise ValueError("permission must be an object")
        permissions = dict(permissions)
        for tool in ("jira_get_issue", "jira_search", "jira_transition_issue"):
            permissions.setdefault(f"mi-jira/{tool}", "allow")
        result["permission"] = permissions
    return result


def write_atomic(path, config):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup = path.with_name(path.name + ".bak")
        shutil.copy2(path, backup)
        os.chmod(backup, stat.S_IRUSR | stat.S_IWUSR)

    fd, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(config, stream, indent=2, ensure_ascii=False)
            stream.write("\n")
        os.chmod(temporary, stat.S_IRUSR | stat.S_IWUSR)
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def redact_config(config):
    serialized = json.loads(json.dumps(config))
    for container_key in ("mcpServers", "servers", "mcp"):
        entry = serialized.get(container_key, {}).get("mi-jira")
        if isinstance(entry, dict) and isinstance(entry.get("headers"), dict):
            token_key = "X-Atlassian-Jira-Personal-Token"
            if token_key in entry["headers"]:
                entry["headers"][token_key] = "<redacted>"
    return serialized


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--client", choices=["claude", "vscode", "kiro", "opencode"], required=True)
    parser.add_argument("--scope", choices=["local", "global"], required=True)
    parser.add_argument("--workspace-root", required=True)
    parser.add_argument("--username", required=True)
    parser.add_argument("--jira-url", default=DEFAULT_JIRA_URL)
    parser.add_argument("--token-stdin", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--home", default=str(Path.home()), help=argparse.SUPPRESS)
    args = parser.parse_args()

    home = Path(args.home).expanduser().resolve()
    workspace = Path(args.workspace_root).expanduser().resolve()
    try:
        path = resolve_config_path(args.client, args.scope, home, workspace)
        config = read_config(path)
        token = read_token(args)
        merged = merge_config(
            config,
            args.client,
            build_entry(args.client, args.username, token, args.jira_url),
        )
    except ValueError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    summary = {
        "client": args.client,
        "scope": args.scope,
        "config_path": str(path),
        "server": "mi-jira",
        "changed_keys": ["mi-jira"],
        "credentials_redacted": True,
        "dry_run": args.dry_run,
        "config_preview": redact_config(merged),
    }
    json.dump(summary, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")

    if not args.dry_run:
        write_atomic(path, merged)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Safely add or update the Feishu MCP configuration."""

import argparse
import getpass
import json
import os
import shutil
import stat
import sys
import tempfile
from pathlib import Path
from urllib.parse import urlparse

URL_ENV = "FEISHU_MCP_URL"
AUTO_APPROVE_TOOLS = [
    "fetch-doc",
    "search-doc",
    "create-doc",
    "update-doc",
    "list-docs",
    "get-comments",
    "add-comments",
    "search-user",
    "get-user",
    "fetch-file",
]


def resolve_config_path(client, scope, home, workspace):
    paths = {
        ("claude", "global"): home / ".claude.json",
        ("claude", "local"): workspace / ".mcp.json",
        ("vscode", "local"): workspace / ".vscode" / "mcp.json",
        ("kiro", "global"): home / ".kiro" / "settings" / "mcp.json",
        ("kiro", "local"): workspace / ".kiro" / "settings" / "mcp.json",
    }
    try:
        return paths[(client, scope)]
    except KeyError as exc:
        raise ValueError(f"unsupported client/scope: {client}/{scope}") from exc


def validate_url(url):
    parsed = urlparse(url.strip())
    if parsed.scheme != "https" or parsed.netloc != "mcp.feishu.cn":
        raise ValueError("Feishu MCP URL must use https://mcp.feishu.cn")
    if not parsed.path.startswith("/mcp/mcp_"):
        raise ValueError("Feishu MCP URL path must start with /mcp/mcp_")
    return parsed.geturl()


def read_url(args):
    url = os.environ.get(URL_ENV)
    if not url and args.url_stdin:
        url = sys.stdin.readline().rstrip("\r\n")
    if not url and sys.stdin.isatty() and not args.dry_run:
        url = getpass.getpass("Feishu MCP private URL: ")
    if args.dry_run and not url:
        return "https://mcp.feishu.cn/mcp/mcp_redacted"
    if not url:
        raise ValueError(f"URL is required via {URL_ENV}, --url-stdin, or secure prompt")
    return validate_url(url)


def read_config(path):
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(
            f"invalid JSON in {path} at line {exc.lineno}, column {exc.colno}"
        ) from exc
    if not isinstance(data, dict):
        raise ValueError(f"top-level JSON in {path} must be an object")
    return data


def build_entry(client, url):
    entry = {"type": "http", "url": url}
    if client == "kiro":
        entry["autoApprove"] = AUTO_APPROVE_TOOLS
    return entry


def merge_config(config, client, entry):
    result = dict(config)
    if client == "vscode":
        result.setdefault("inputs", [])
        container_key = "servers"
    else:
        container_key = "mcpServers"
    container = result.get(container_key)
    if container is None:
        container = {}
    if not isinstance(container, dict):
        raise ValueError(f"{container_key} must be an object")
    container = dict(container)
    container["feishu-mcp"] = entry
    result[container_key] = container
    return result


def write_atomic(path, config):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup = path.with_name(path.name + ".bak")
        shutil.copy2(path, backup)
        os.chmod(backup, stat.S_IRUSR | stat.S_IWUSR)

    fd, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(config, stream, indent=2, ensure_ascii=False)
            stream.write("\n")
        os.chmod(temporary, stat.S_IRUSR | stat.S_IWUSR)
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def redact_config(config):
    serialized = json.loads(json.dumps(config))
    for container_key in ("mcpServers", "servers"):
        entry = serialized.get(container_key, {}).get("feishu-mcp")
        if isinstance(entry, dict) and "url" in entry:
            entry["url"] = "https://mcp.feishu.cn/mcp/<redacted>"
    return serialized


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--client", choices=["claude", "vscode", "kiro"], required=True)
    parser.add_argument("--scope", choices=["local", "global"], required=True)
    parser.add_argument("--workspace-root", required=True)
    parser.add_argument("--url-stdin", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--home", default=str(Path.home()), help=argparse.SUPPRESS)
    args = parser.parse_args()

    home = Path(args.home).expanduser().resolve()
    workspace = Path(args.workspace_root).expanduser().resolve()
    try:
        path = resolve_config_path(args.client, args.scope, home, workspace)
        config = read_config(path)
